// Differential test of the function-local tables of the AAC decoder glue (generated by
// crates/aacdec/src/aacdecoder/gen_tables.py): map_sbrRatio_2_nAnaBands of CAacDecoder_Init()
// and b[], a[] of applyDrcLevelNormalization(), element by element against the declarations of
// the C++ functions compiled at file scope (shim aacdec_tables_glue.cpp).

use fdk_aac_rs_aacdec::aacdec_drc::tables::{SMOOTH_A, SMOOTH_B};
use fdk_aac_rs_aacdec::aacdecoder::tables::MAP_SBR_RATIO_2_N_ANA_BANDS;
use fdk_aac_rs_cref::aacdec_tables_glue as c;

fn check(name: &str, f: unsafe extern "C" fn(*mut i32) -> i32, port: &[i32]) {
    let mut out = [0x5A5A_5A5Ai32; 64];
    let n = unsafe { f(out.as_mut_ptr()) };
    assert_eq!(n as usize, port.len(), "{name}: number of elements");
    for (i, (&r, &p)) in out[..n as usize].iter().zip(port).enumerate() {
        assert_eq!(r, p, "{name}[{i}]");
    }
}

#[test]
fn function_local_tables() {
    let v: Vec<i32> = MAP_SBR_RATIO_2_N_ANA_BANDS.iter().map(|&x| x as i32).collect();
    check("map_sbrRatio_2_nAnaBands", c::cref_tables_glue_map_sbr_ratio_2_n_ana_bands, &v);
    let v: Vec<i32> = SMOOTH_B.iter().map(|&x| x as i32).collect();
    check("b", c::cref_tables_glue_smooth_b, &v);
    let v: Vec<i32> = SMOOTH_A.iter().map(|&x| x as i32).collect();
    check("a", c::cref_tables_glue_smooth_a, &v);
}
